def subhero(title,desc,path,parent=None):
 crumbs=[('Ana sayfa','/')]+([parent]if parent and parent[1]!='/' else [])+[(title,path)]
 return '<section class="subhero"><div class="wrap"><nav class="breadcrumbs" aria-label="İçerik yolu">'+''.join(f'<a href="{p}">{n}</a><span aria-hidden="true">/</span>'for n,p in crumbs[:-1])+f'<span>{title}</span></nav><span class="eyebrow" style="color:var(--yellow)">İZMİR OTO ÇEKİCİNİZ · 7/24</span><h1>{title}</h1><p class="lead">{desc}</p>{buttons()}</div></section>'
def detail(path,title,desc,sections,questions=None,parent=('Hizmetler','/hizmetler/'),service=None):
 sections=list(sections)+EXTRA_SECTIONS.get(path,[])
 if path in ('/bolgeler/gaziemir/','/bolgeler/menderes/'):
  sections=district_sections(path.strip('/').split('/')[-1])+sections
 article=''.join(f'<section><h2>{heading}</h2><div class="region-copy">{text}</div></section>'for heading,text in sections)
 if path.startswith('/hizmetler/') and path.strip('/').split('/')[-1] in SERVICE_SCENARIOS:
  article+=scenario_html(SERVICE_SCENARIOS[path.strip('/').split('/')[-1]])
 if questions:article+='<section><h2>Sık sorulan sorular</h2>'+faq_html(questions)+'</section>'
 body=subhero(title,desc,path,parent)+f'<section class="section"><div class="wrap detail-grid"><article class="article">{article}</article><aside class="aside"><span class="eyebrow">7/24 İLETİŞİM</span><h3>Konumunuzu paylaşın.</h3><p>Aracın bulunduğu nokta, marka-model ve sorunu iletin. Ekipman, ücret ve tahmini varış süresini görüşmede netleştirelim.</p><a class="btn" href="{TEL}">{PHONE}</a><a class="btn secondary" href="{WA}">WhatsApp ile yazın</a><ul class="checks"><li>İzmir’in 30 ilçesinde hizmet</li><li>İzmir geneli talep değerlendirmesi</li><li>Haftanın her günü, 24 saat</li></ul></aside></div></section>'
 layout(path,title+' | İzmir Oto Çekiciniz',desc,body,crumbs=[('Ana sayfa','/')]+([parent]if parent[1]!='/' else [])+[(title,path)],service=service)
content={
'oto-cekici':[
('Hareket edemeyen araç için taşıma','Motor arızası, kaza veya yürür aksam sorunu nedeniyle güvenle sürülemeyen aracın alınacağı ve teslim edileceği noktaları belirleriz. Binek, SUV veya hafif ticari araçta taşıma planı; ölçü, ağırlık, yerden yükseklik ve tekerleklerin durumuna göre değişir.'),
('Kayar kasa seçimi ve yükleme erişimi','Araç kapalı otoparkta, eğimli bir alanda veya dar sokakta ise bu bilgiyi çağrıda paylaşın. Yükleme için aracın çevresindeki alanı ve giriş yüksekliğini değerlendiririz. Otomatik vites, dört çeker sistem veya kilitli tekerlek durumunu bilmek uygun ekipmanın seçilmesine yardımcı olur.'),
('Servis teslimini önceden planlayın','Aracın hangi servise veya adrese götürüleceğini belirtin. Servisin açık olması ve aracı kabul edebilmesi, taşımanın tamamlanması için önemlidir. Teslim adresi değişirse mesafe ve hizmet kapsamını yeniden netleştiririz.')],
'aku-takviye':[
('Marş sorununun kaynağı değerlendirilir','Aracın marş almaması her zaman aküden kaynaklanmaz. Gösterge ışıkları, marş sesi, aracın ne kadar süredir kullanılmadığı ve son yaşanan belirtiler ilk değerlendirmede yardımcı olur. Marka-model ve yakıt bilgisini paylaşarak yerinde takviye uygunluğunu görüşebilirsiniz.'),
('Araca uygun bağlantı ve erişim','Takviye noktası ve işlem yöntemi araç modeline göre değişebilir. Akünün konumu, aracın bulunduğu alan ve üretici talimatları dikkate alınır. Elektrikli veya hibrit araç olduğunu özellikle belirtin; her araçta aynı bağlantı yöntemi uygulanmaz.'),
('Takviye sonrası sorun devam ederse','Araç çalışsa bile akü, şarj sistemi veya elektrik arızası devam ediyor olabilir. Tekrarlayan marş sorununda yalnızca takviye ile kalıcı çözüm vaadi verilmez. Belirtiye göre mobil oto elektrik veya uygun servise transfer seçeneği değerlendirilir.')],
'oto-elektrik':[
('Belirtileri ilk görüşmede paylaşın','Marş basmaması, şarj uyarısı, aydınlatma sorunu veya beklenmedik elektrik kesintisi farklı nedenlere dayanabilir. Araç modeliyle birlikte hangi uyarıların görüldüğünü ve sorunun ne zaman başladığını anlatın. Bu bilgiler yerinde değerlendirme ile servis transferi arasında seçim yapmaya yardımcı olur.'),
('Mobil müdahalenin kapsamı','Yerinde işlem uygunluğu arızanın türü, ekipman ihtiyacı ve aracın güvenli erişimine bağlıdır. Yol kenarında her elektrik arızası çözülemez; kapsamlı söküm, parça temini veya servis ekipmanı gerektiğinde taşıma planlanır. Belirti bilgisi olmadan kesin onarım veya parça değişimi sözü verilmez.'),
('Akü ile elektrik arızasını ayırmak','Akünün bitmesi, marş sistemi sorunu ve şarj sistemi problemi birbirine benzer belirtiler gösterebilir. İlk görüşmede takviye talebinizi anlatırken önceki müdahaleleri de belirtin. Böylece aynı işlemi tekrarlamak yerine uygun destek seçeneği belirlenebilir.')],
'oto-kurtarma':[
('Taşıma öncesi kurtarma ihtiyacı','Kaza sonrası hareket edemeyen, zemine oturmuş veya standart yükleme alanı bulunmayan araçlar için önce bulunduğu noktadan alınma koşulları değerlendirilir. Araç fotoğrafı, tekerleklerin durumu ve çevredeki erişim alanı ekipman planlamasında önemlidir.'),
('Konum ve zemin koşulları','Eğim, yumuşak zemin, kapalı giriş veya aracın yol seviyesinden aşağıda olması işlem kapsamını değiştirebilir. Yalnızca araç modelini bilmek yeterli değildir; bulunduğu konumun fotoğrafını ve konum bağlantısını paylaşın. Vinç veya ek ekipman gereksinimi bu bilgiler üzerinden görüşülür.'),
('Kurtarma ve teslim ayrı değerlendirilir','Aracın bulunduğu yerden alınması ile servise taşınması farklı aşamalardır. Kurtarma koşulları, taşıma mesafesi ve teslim noktası birlikte ücretlendirmeyi etkiler. Aracın hasar durumu ve varsa yük bilgisi yönlendirme öncesinde netleştirilir.')],
'agir-vasita-kurtarma':[
('Tonaj ve araç bilgisiyle planlama','Tır, kamyon ve otobüste kurtarma ihtiyacı değerlendirilirken araç tipi, toplam ağırlık, yük durumu ve hareket edebilirlik bilgileri gereklidir. Çekici-dorse bağlantısı veya aks hasarı varsa ayrıca belirtin. Ağır vasıta için binek araç taşımasından farklı ekipman gerekebilir.'),
('Yol erişimi ve operasyon alanı','Aracın bulunduğu yolun yönü, yakın bağlantı noktası ve etrafındaki çalışma alanı değerlendirilir. Devrilme veya zor zemin gibi durumlarda fotoğraf ve konum bilgisi özellikle önem taşır. Müdahale yöntemi ve uygun ekipman belirlenmeden standart bir kurtarma süresi verilemez.'),
('Yük ve teslim bilgisi','Araçta taşınan yük, kurtarma ve transfer koşullarını değiştirebilir. Yükün türü ve durumu ile işletmenin teslim tercihi görüşmede paylaşılmalıdır. Servis, depo veya başka bir teslim noktası seçildiğinde erişim ve kabul koşulları da netleştirilir.')],
'agir-ticari-cekici':[
('Ticari araçta transfer ihtiyacı','Ticari araçta arıza nedeniyle servise taşıma veya planlı transfer talebi için marka-model, araç ölçüleri ve ağırlık bilgisi alınır. Kasa yapısı, dingil düzeni veya özel üstyapı varsa belirtin. Taşıma yöntemi bu bilgilere göre seçilir.'),
('Yüklü araçlarda ek değerlendirme','Araç yüklüyse toplam ağırlık, yükün durumu ve transfer sırasında korunması gereken koşullar görüşülür. Yüklü ve boş aracın ekipman ihtiyacı aynı olmayabilir. Fabrika, depo veya sanayi girişindeki yükleme erişimini önceden paylaşmak planlamayı kolaylaştırır.'),
('Kurtarma mı, doğrudan taşıma mı?','Araç yüklemeye uygun bir noktada ve erişilebilir durumdaysa transfer planlanabilir. Araç devrilmiş, sıkışmış veya yürür aksamında ağır hasar oluşmuşsa kurtarma gereksinimi ayrıca değerlendirilir. Bu ayrım hizmet kapsamı ve ücretin görüşülmesinde önemlidir.')],
'motosiklet-cekici':[
('Motosiklete uygun taşıma','Motosikletin tipi, ağırlığı ve hareket durumu yükleme yöntemi için gereklidir. Scooter, yol motosikleti veya daha ağır bir model olduğunu ve varsa yan çanta gibi ek donanımları belirtin. Taşıma hazırlığı yalnızca motor hacmine göre yapılmaz.'),
('Sabitleme ve hasar bilgisi','Kaza veya arıza sonrası direksiyon, tekerlek ve fren sisteminin durumu değerlendirilir. Tekerlek kilidi, gidon hareketinin kısıtlı olması veya düşmeye bağlı hasar varsa çağrıda paylaşın. Motosiklete uygun yükleme ve sabitleme yöntemi bu bilgilere göre planlanır.'),
('Teslim noktasını belirlemek','Yetkili servis, tamirhane veya tercih edilen adrese transfer için konum ve teslim bilgisi gerekir. Motosikletin anahtarı ve varsa güvenlik kilitleri hakkında bilgi verin. Servis kabul saatini netleştirmek teslim sırasında beklemeyi azaltabilir.')],
'lastik-yol-yardim':[
('Lastik sorununuzu tarif edin','Patlak lastik, hava kaybı veya lastik hasarında araç modeli, sorunun bulunduğu tekerlek ve aracın mevcut konumu paylaşılmalıdır. Yedek lastik olup olmadığını ve kullanıma uygun durumunu belirtin. Yerinde destek seçeneği araç ve erişim koşullarına bağlıdır.'),
('Yerinde yardım uygun değilse','Aracın güvenli çalışma alanı bulunmaması, birden fazla lastikte sorun olması veya yürür aksam hasarı taşıma ihtiyacı doğurabilir. Her lastik problemine yol kenarında onarım sözü verilmez. Koşullara göre uygun lastik servisine ya da tercih ettiğiniz teslim noktasına transfer değerlendirilir.'),
('Çağrıda hazırlayabileceğiniz bilgiler','Konum bağlantısı, lastik veya tekerlek fotoğrafı ve teslim tercihi ilk görüşmeyi kolaylaştırır. Araç kapalı otoparkta ya da yüksekliği sınırlı bir alandaysa bunu belirtin. Gerekli destek, toplam ücret ve tahmini yönlendirme süresi görüşmede netleştirilir.')]
}
