layout('/404/','Sayfa bulunamadı | İzmir Oto Çekiciniz','Aradığınız sayfa bulunamadı. Ana sayfaya veya hizmet rehberine dönebilirsiniz.',subhero('Bu sayfa bulunamadı.','Hizmetlerimizi inceleyebilir veya çekici talebi için bize ulaşabilirsiniz.','/404/')+'<section class="section"><div class="wrap"><a class="btn" href="/">Ana sayfaya dön</a></div></section>',ready=False)
