(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+e(u)+'</loc></url>\n'for u in urls)+'</urlset>\n')
(DIST/'robots.txt').write_text('User-agent: *\nAllow: /\n'+('Sitemap: '+ORIGIN+'/sitemap.xml\n'if PUBLIC else ''))
(DIST/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n'+('  X-Robots-Tag: noindex, follow\n'if not PUBLIC else '')+'\n/assets/*\n  Cache-Control: public, max-age=86400\n')
(ROOT/'pages.json').write_text(json.dumps({'mode':'public'if PUBLIC else 'private-preview','origin':ORIGIN,'pages':pages},ensure_ascii=False,indent=2))
backlog=json.loads((ROOT/'content-backlog.json').read_text())
for item in backlog['regions']:
 item['status']='rendered'
 item['canonical_path']=reference_mapping.get(item['reference_path'])
backlog['note']='Tüm referans bölgeleri oluşturuldu. Eşdeğer adlar tek içerik adresinde; tüm içerik sayfaları işletme sahibinin isteğiyle indekslemeye uygun olarak ayarlanır.'
(ROOT/'content-backlog.json').write_text(json.dumps(backlog,ensure_ascii=False,indent=2))
# İlk yayın için alan adına göre hazırlanmış sitemap; özel önizleme bunu Google'a duyurmaz.
launch_urls=[ORIGIN+p['path']for p in pages if p['ready']]
launch_dir=ROOT/'launch';launch_dir.mkdir(exist_ok=True)
(launch_dir/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+e(u)+'</loc></url>\n'for u in launch_urls)+'</urlset>\n')
(launch_dir/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
# Referans kapsamının tamamını yeni tekil içerik adreslerine eşleştir.
reference_mapping.update({'/':'/','/cekici':'/hizmetler/oto-cekici/','/aku-takviye':'/hizmetler/aku-takviye/','/oto-elektrik':'/hizmetler/oto-elektrik/','/motorsiklet-cekici':'/hizmetler/motosiklet-cekici/','/agir-vasita-kurtarma':'/hizmetler/agir-vasita-kurtarma/','/agir-ticari-cekici':'/hizmetler/agir-ticari-cekici/','/oto-kurtarma':'/hizmetler/oto-kurtarma/','/lastik-yol-yardim':'/hizmetler/lastik-yol-yardim/','/fiyatlar':'/fiyatlandirma/','/hizmet-bolgeleri':'/hizmet-bolgeleri/','/iletisim':'/iletisim/'})
redirects={}
for old,new in reference_mapping.items():
 if old!='/' and old!=new.rstrip('/'):
  redirects[old]=new;redirects[old+'/']=new
for p in pages:
 if p['path']!='/':redirects[p['path'].rstrip('/')]=p['path']
(DIST/'_redirects').write_text(''.join(old+' '+new+' 301\n'for old,new in sorted(redirects.items())))
(ROOT/'url-mapping.json').write_text(json.dumps({'origin':ORIGIN,'reference_mapping':reference_mapping,'redirects':redirects},ensure_ascii=False,indent=2))
(ROOT/'publication-plan.json').write_text(json.dumps({'domain':ORIGIN,'phase_one':[p['path']for p in pages if p['ready']],'phase_two':[p['path']for p in pages if not p['ready'] and p['path']!='/404/'],'note':'İşletme sahibinin talebiyle 262 içerik sayfası indekslemeye uygun ve sitemap kapsamındadır. 404 kapsam dışındadır. Alan adı, kamuya açık erişim ve Search Console gönderimi ayrı yayın adımlarıdır.'},ensure_ascii=False,indent=2))
